int main(){try{MilitaryCombatConditionState s;s.entry_tick=7;s.units={{"unit","camp","military:4",Integer(20),Integer(70),7500,{}}};auto json=military_combat_conditions_codec::encode(s);auto restored=take(military_combat_conditions_codec::decode(json));check(compare_boundary(json,military_combat_conditions_codec::encode(restored)).values_equal,"exact ordered roundtrip");auto duplicate=json;duplicate.as<BoundaryValue::Dict>()->push_back(duplicate.as<BoundaryValue::Dict>()->front());check(!military_combat_conditions_codec::decode(duplicate).ok,"duplicate state key rejected");duplicate=json;auto* row=(*duplicate.find("units")->as<BoundaryValue::Array>())[0].as<BoundaryValue::Dict>();row->push_back(row->front());check(!military_combat_conditions_codec::decode(duplicate).ok,"nested unit duplicate rejected");auto bad=json;*(*bad.find("units")->as<BoundaryValue::Array>())[0].find("efficiency_bp")=BoundaryValue{Integer(10000)};check(!military_combat_conditions_codec::decode(bad).ok,"forged efficiency rejected before gameplay");bad=json;bad.find("units")->as<BoundaryValue::Array>()->push_back(bad.find("units")->as<BoundaryValue::Array>()->front());check(!military_combat_conditions_codec::decode(bad).ok,"duplicate unit rejected");
 constexpr auto old=military_garrison_rest_checkpoint_feature|military_command_shock_checkpoint_feature|military_rout_checkpoint_feature|military_supply_attrition_checkpoint_feature|military_recovery_checkpoint_feature;constexpr auto feature=old|military_combat_conditions_checkpoint_feature;MilitaryBattleRecord b;b.id="battle:8";b.created_tick=7;BattleUnit unit;unit.unit_id="unit";b.units={unit};CodecVisitor::Buffer legacy;CodecVisitor prior(legacy);prior.schema_features=old;good(battle_codec::visit(prior,b));good(prior.finish());const auto legacy_input=legacy;MilitaryBattleRecord recovered;CodecVisitor old_read(legacy_input);old_read.schema_features=old;good(battle_codec::visit(old_read,recovered));good(old_read.finish());check(!recovered.combat_conditions,"old12 has no implicit condition snapshot");CodecVisitor::Buffer repeated;CodecVisitor again(repeated);again.schema_features=old;good(battle_codec::visit(again,recovered));good(again.finish());check(legacy==repeated,"old12 roundtrip byte equality");b.combat_conditions=s;CodecVisitor::Buffer saved;CodecVisitor writer(saved);writer.schema_features=feature;good(battle_codec::visit(writer,b));good(writer.finish());const auto data=saved;MilitaryBattleRecord decoded;CodecVisitor reader(data);reader.schema_features=feature;good(battle_codec::visit(reader,decoded));good(reader.finish());check(decoded.combat_conditions&&decoded.combat_conditions->units[0].fatigue==70,"new frame preserves original frozen condition");CodecVisitor::Buffer refused;CodecVisitor old_writer(refused);old_writer.schema_features=old;check(!battle_codec::visit(old_writer,b).ok,"new condition cannot hide in old12");auto damaged=saved;damaged.pop_back();const auto truncated=damaged;MilitaryBattleRecord broken;CodecVisitor broken_read(truncated);broken_read.schema_features=feature;auto status=battle_codec::visit(broken_read,broken);check(!status.ok||!broken_read.finish().ok,"truncated new frame rejected");check(!validate_military_combat_conditions_modules({{military_combat_conditions_module,"1"}}).ok,"full12 prerequisite required");check(!validate_military_combat_conditions_modules({{military_combat_conditions_module,"2"}}).ok,"future marker rejected");check(validate_military_combat_conditions_modules({}).ok,"old disabled profile allowed");std::cout<<"MILITARY_COMBAT_CONDITION_CODEC="<<checks<<" FAILURES=0 SCOPE=CODEC_SHAPE_COMPONENT\n";return 0;
 }catch(const std::exception& e){std::cerr<<"MILITARY_COMBAT_CONDITION_CODEC_FAIL "<<checks<<" "<<e.what()<<'\n';return 1;}}
